async function getCustomOptions(tier, slot){
  return (await sGet(`custom-options:${tier}:${slot}`)) || [];
}
async function allOptionsFor(tier, slot){
  const custom = await getCustomOptions(tier, slot);
  return [...MEAL_DATA[tier][slot], ...custom];
}

